style.css:
@-moz-document domain("k12.com") {
/* Change the side panel color to be a gradient */

header.ic-app-header.no-print {
  background: #0035F0;
   background: linear-gradient(180deg, rgba(0, 53, 240, 1) 0%, rgba(51, 0, 120, 1) 100%);
   font-family: 'Gill Sans', 'Gill Sans MT', Calibri, 'Trebuchet MS', sans-serif;
}

/* Buttons are S M O O T H */

a.ic-app-header__menu-list-link {
  transition: all 0.8s ease;
}

/* Lets make you a bit darker*/

div.CompletedItemsFacade-styles__root.planner-completed-items {
  background-color: rgb(230,230,230);
  transition: all 0.3s ease;
}

/* And have some hover action */
div.CompletedItemsFacade-styles__root.planner-completed-items:hover {
  background-color: rgb(250,250,250)
}

/* Hover the oppisite way around */
div.PlannerItem-styles__root.planner-item {
  transition: all 0.3s ease-out;
  background-color: rgb(255,255,255);
}

div.PlannerItem-styles__root.planner-item:hover {
  transition: all 0.4s ease-in;
  background-color: rgb(230,230,230);
}

/* Calendar Styling (rounded buttons) */

button.btn.calendar-button, button.btn {
  border-radius: 10px;
}

/* Weekend Highlighting */

td.fc-day.fc-widget-content.fc-sun.fc-past, 
td.fc-day.fc-widget-content.fc-sat.fc-past, 
td.fc-day.fc-widget-content.fc-sun.fc-future, td.fc-day.fc-widget-content.fc-sat.fc-future {
  background-color: rgb(230,230,230)
}

/* Inbox hover */

div.css-11i7ws9-view {
  transition: all 0.3s ease;
}

div.css-11i7ws9-view:hover {
  transition: all 0.3s ease;
  background-color: rgb(240,240,240)
}

/* YAY! we're done! feel free to edit this! :D */
}
